// FUNCTION: BFME2 0x0032758A size=99 name=?doRadioUnselect@@YAXPAVGameWindow@@HH0@Z evidence=N:ledger tier=B hypothesis:name:invented
void doRadioUnselect(GameWindow *window, Int group, Int screen, GameWindow *except)
{
	// A radio button of the same group and screen, other than the exception, is deselected.
	if (window != except && (window->winGetStyle() & 0x2))
	{
		// The radio button gadget's user data: screen at +0, group at +4.
		Int *radioData = (Int *)window->winGetUserData();

		if (radioData[1] == group && radioData[0] == screen)
		{
			WinInstanceData *instData = window->winGetInstanceData();

			instData->m_state &= ~0x4;
		}
	}

	// Recurse into the children.
	for (GameWindow *child = window->winGetChild(); child; child = child->winGetNext())
		doRadioUnselect(child, group, screen, except);
}

// FUNCTION: BFME2 0x003275ED size=67 name=?unselectOtherRadioOfGroup@@YAXHHPAVGameWindow@@@Z evidence=N:ledger tier=B hypothesis:K
void unselectOtherRadioOfGroup(Int group, Int screen, GameWindow *except)
{
	GameWindow *window = TheWindowManager->winGetWindowList();

	for (window = TheWindowManager->winGetWindowList(); window; window = window->winGetNext())
		doRadioUnselect(window, group, screen, except);
}
